function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function j($v):string{return json_encode($v,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
function fmt($v):string{if(!is_numeric($v))return (string)$v;$f=(float)$v;return $f==0?'0':(abs($f)<.0001||abs($f)>=1e6?sprintf('%.6e',$f):rtrim(rtrim(sprintf('%.6f',$f),'0'),'.'));}
function security():void{header_remove('X-Powered-By');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('X-Frame-Options: DENY');header('Permissions-Policy: camera=(), microphone=(), geolocation=()');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-src 'none'; frame-ancestors 'none'; form-action 'self'");}
function start(string $title,string $desc,string $path,bool $noindex=false):void{security();if($noindex){header('X-Robots-Tag: noindex');header('Cache-Control: no-store');}$url=ORIGIN.$path;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=h($title)?> | Beyond Spacetime</title><meta name="description" content="<?=h($desc)?>"><meta name="robots" content="<?=$noindex?'noindex, follow':'index, follow'?>"><link rel="canonical" href="<?=h($url)?>"><meta property="og:title" content="<?=h($title)?>"><meta property="og:description" content="<?=h($desc)?>"><meta property="og:url" content="<?=h($url)?>"><meta property="og:image" content="<?=ORIGIN?>/evidence/assets/banner.webp"><meta name="theme-color" content="#08111f"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/research/assets/research.css?v=1.5.0"><script src="/research/assets/research.js?v=1.5.0" defer></script><script type="application/ld+json"><?=j(['@context'=>'https://schema.org','@graph'=>[['@type'=>'WebPage','@id'=>$url.'#page','name'=>$title,'url'=>$url,'description'=>$desc,'isPartOf'=>['@type'=>'WebSite','name'=>'Beyond Spacetime','url'=>ORIGIN.'/']],['@type'=>'BreadcrumbList','itemListElement'=>array_merge([['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>ORIGIN.'/'],['@type'=>'ListItem','position'=>2,'name'=>'Research workspace','item'=>ORIGIN.ROOT]],$path!==ROOT?[['@type'=>'ListItem','position'=>3,'name'=>$title,'item'=>$url]]:[])]]])?></script><link rel="stylesheet" href="/museum/assets/crossnav.css?v=2.2.1"></head><body><a class="skip" href="#main">Skip to main content</a><header><div class="nav"><a class="brand" href="/"><img src="/evidence/assets/compass.png" alt="" width="44" height="44"><span>BEYOND<span class="gold">SPACETIME</span><small>RESEARCH WORKSPACE</small></span></a><nav aria-label="Main navigation"><?php if(\bsp_legacy_available()):?><a href="/explore/">Explore 3D</a><?php endif;?><a href="/foundations/">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/" <?=$path===ROOT?'aria-current="page"':''?>>Workspace</a><a href="/research/presets/" <?=$path===ROOT.'presets/'?'aria-current="page"':''?>>Investigations</a><a href="/research/protocol/" <?=$path===ROOT.'protocol/'?'aria-current="page"':''?>>Agent protocol</a></nav><a class="arc" href="https://arcsecs.com/read-scientific-paper/">Original research ↗</a></div></header><nav class="museum-crossnav" aria-label="Museum exhibits"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/foundations/">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/" aria-current="true">Workspace</a><a href="/model-comparison/">Compare</a><a href="/timeline/">Timeline</a><a href="/global/">Languages</a><a href="/offline/">Offline</a><a href="/visualizations/">Visualize</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/">Design</a><a href="/universal-time/">Time</a></nav><main id="main" class="wrap"><div class="crumb"><a href="/">Home</a> / <a href="/research/">Research</a><?=$path!==ROOT?' / '.h($title):''?></div><?php }
function endpage():void{?><footer><div><strong>Beyond Spacetime · Research workspace</strong><p>Executable learning controls, not new observational evidence. Authoritative book and papers remain at ArcSecs.com.</p></div><div><a href="/research/catalog.json">Machine catalog</a><a href="/research/protocol/">Agent API documentation</a><a href="/research/sitemap.xml">Sitemap</a></div><div><a href="/foundations/">Twelve foundations</a><a href="/evidence/">Evidence ledger</a><a href="https://arcsecs.com/">ArcSecs ↗</a></div></footer></main></body></html><?php }
function chart(array $r):void{$rows=$r['rows'];$xmin=$rows[0][0];$xmax=$rows[count($rows)-1][0];$lo=0.;$hi=0.;foreach($rows as $row)foreach(array_slice($row,1) as $y){$lo=min($lo,$y);$hi=max($hi,$y);}if($hi===$lo)$hi+=1;if($xmin===$xmax)$xmax+=1;$x=fn($v)=>65+($v-$xmin)/($xmax-$xmin)*605;$y=fn($v)=>217-($v-$lo)/($hi-$lo)*190;?><figure class="chart-box"><svg viewBox="0 0 700 260" role="img" aria-label="<?=h(($r['xLabel']??$r['x']).' versus '.implode(', ',$r['series']))?>"><?php for($i=0;$i<5;$i++):$v=$hi-($hi-$lo)*$i/4;$xx=$xmin+($xmax-$xmin)*$i/4;?><line x1="65" x2="670" y1="<?=$y($v)?>" y2="<?=$y($v)?>" class="gridline"/><text x="60" y="<?=$y($v)+4?>" text-anchor="end"><?=h(fmt($v))?></text><text x="<?=$x($xx)?>" y="235" text-anchor="middle"><?=h(fmt($xx))?></text><?php endfor;foreach($r['series'] as $i=>$s):?><polyline class="series s<?=$i?>" points="<?=h(implode(' ',array_map(fn($row)=>sprintf('%.2f,%.2f',$x($row[0]),$y($row[$i+1])),$rows)))?>"/><?php endforeach;?><text x="367" y="254" text-anchor="middle"><?=h($r['xLabel']??$r['x'])?></text></svg><figcaption><?php foreach($r['series'] as $i=>$s):?><span><i class="swatch s<?=$i?>"></i><?=h($s)?></span><?php endforeach;?></figcaption></figure><?php }
function render_result(array $r,?bool $match=null):void{?><section class="section" aria-labelledby="results-title"><div class="section-heading"><div><span class="eyebrow">REPRODUCIBLE INVESTIGATION</span><h2 id="results-title"><?=h($r['recipe']['title'])?></h2></div><span class="pill"><?=count($r['runs'])?> completed cases</span></div><p><?=h($r['recipe']['question'])?></p><p class="notice"><?=h($r['interpretation'])?></p><?php if($match!==null):?><p class="notice">Replay digest: <?=$match?'matches the supplied digest.':'differs from the supplied digest.'?> This comparison does not establish authenticity.</p><?php endif;?><div class="actions"><button type="button" id="export-result" hidden>Export complete JSON</button><button type="button" id="export-metrics" hidden>Export metrics CSV</button><button type="button" id="export-samples" hidden>Export sample CSV</button></div><div class="result-grid"><?php foreach($r['runs'] as $c):$v=$c['result'];?><article class="panel case-output"><span class="eyebrow"><?=h($c['id'])?> · <?=h($c['model_title'])?></span><h3><?=h($c['label'])?></h3><div class="metric-grid"><?php foreach($v['metrics'] as $m):?><div class="metric"><span><?=h($m['label'])?></span><strong><?=h(fmt($m['value']))?> <small><?=h($m['unit'])?></small></strong></div><?php endforeach;?></div><?php chart($v);?><p class="muted">Parameters: <?=h(encode($v['parameters']))?></p><p><?=h($v['limitation'])?></p><a href="<?=h($c['url'])?>">Original learning control →</a></article><?php endforeach;?></div><h2 class="section">Within-model differences</h2><?php if(!$r['comparisons']):?><p>No repeated model. Add a second case of the same model to compute numerical differences.</p><?php endif;foreach($r['comparisons'] as $c):?><section class="panel comparison"><h3><?=h($c['candidate_case'].' minus '.$c['reference_case'])?></h3><p class="muted"><?=h($c['model'])?></p><div class="table-scroll"><table><thead><tr><th scope="col">Metric</th><th scope="col">Reference</th><th scope="col">Candidate</th><th scope="col">Difference</th></tr></thead><tbody><?php foreach($c['metrics'] as $m):?><tr><th scope="row"><?=h($m['label'].' '.$m['unit'])?></th><td><?=h(fmt($m['reference']))?></td><td><?=h(fmt($m['candidate']))?></td><td><?=h($m['delta']===null?'—':fmt($m['delta']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php endforeach;?><h2 class="section">Evidence and open validation gates</h2><div class="record-grid"><?php foreach($r['evidence'] as $v):?><article class="panel"><span class="eyebrow"><?=h(\corpus()['statuses'][$v['status']])?></span><h3><a href="<?=h($v['url'])?>"><?=h($v['title'])?></a></h3><p><?=h($v['finding'])?></p><p class="muted"><?=h($v['limitation'])?></p><small>Linked by <?=h(implode(', ',$v['linked_by']))?> · manuscript pp. <?=h(implode(', ',$v['pages']))?></small></article><?php endforeach;?></div><?php foreach($r['gates'] as $g):?><details class="panel"><summary><?=h($g['id'].' — '.$g['title'])?> · Completion not established</summary><p><?=h($g['pass_condition'])?></p></details><?php endforeach;?><section class="panel provenance section"><h2>Provenance and replay</h2><p>Recipe SHA-256 <code><?=h($r['recipe_sha256'])?></code></p><p>Result SHA-256 <code><?=h($r['result_sha256'])?></code></p><p>PHP <?=h($r['provenance']['php_version'])?> · workspace <?=h(VERSION)?></p><details><summary>Installed calculation and source file hashes</summary><?php foreach($r['provenance']['source_files_sha256'] as $f=>$hash):?><p><?=h($f)?> <code><?=h($hash)?></code></p><?php endforeach;?></details></section><script type="application/json" id="result-data"><?=j($r)?></script></section><?php }
function workspace():void{$method=$_SERVER['REQUEST_METHOD']??'GET';$id=is_string($_GET['preset']??null)&&isset(presets()[$_GET['preset']])?$_GET['preset']:'escape';$raw=json_encode(presets()[$id]['plan'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$r=null;$err='';$expected='';$match=null;if($method==='POST'){try{$raw=is_string($_POST['recipe']??null)?$_POST['recipe']:'';$p=decode($raw);$expected=$_POST['expected']??'';if(!is_string($expected)||($expected!==''&&!preg_match('/^[0-9a-f]{64}$/D',$expected)))throw new \InvalidArgumentException('Invalid replay digest.');$r=evaluate($p);$match=$expected===''?null:hash_equals($expected,$r['result_sha256']);$raw=json_encode($r['recipe'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if(($_POST['action']??'')==='download'){security();header('Content-Type: application/json');header('Content-Disposition: attachment; filename="beyondspacetime-investigation.json"');header('Cache-Control: no-store');echo encode($r);return;}}catch(\InvalidArgumentException|\JsonException $e){http_response_code(400);$err=$e->getMessage();$raw=substr($raw,0,65536);$expected='';}}elseif(!in_array($method,['GET','HEAD'],true)){http_response_code(405);header('Allow: GET, HEAD, POST');return;}
start('Scientific research workspace','Build and replay multi-case investigations across the ArcSecs foundations and evidence controls, with a native AG-UI interface.',ROOT,$method==='POST'||isset($_GET['preset']));?><section class="intro"><span class="eyebrow gold">V1.5 · RESEARCH COMMAND CENTER</span><h1>Investigate. Compare. Reproduce.</h1><p class="lead">Build an ordered scientific investigation using the existing calculation engines. Compare controls, trace related evidence and export a record that can be recomputed by humans or machine intelligence.</p><div class="actions"><a class="button secondary" href="/research/presets/">Explore guided investigations</a><a class="button secondary" href="/research/protocol/">Agent & API guide</a></div></section><div class="stats"><div><strong>15</strong><span>Available models</span></div><div><strong>8</strong><span>Cases per run</span></div><div><strong>26</strong><span>Evidence records</span></div><div><strong>7</strong><span>Open validation gates</span></div></div><form id="recipe-form" method="post" action="/research/"><section class="panel editor"><div class="section-heading"><h2>Investigation recipe</h2><span class="pill">No account or external AI</span></div><p>Use the visual builder or edit the JSON directly. A recipe contains parameters and selected evidence, never trusted imported results.</p><?php if($err):?><p class="notice error" role="alert"><?=h($err)?></p><?php endif;?><div id="builder" hidden><div class="field"><label for="plan-title">Investigation title</label><input id="plan-title" maxlength="160"></div><div class="field"><label for="plan-question">Research question</label><input id="plan-question" maxlength="600"></div><div id="case-builder"></div><div class="actions"><button type="button" id="add-case" class="secondary">Add a case</button></div><details><summary>Choose additional evidence records</summary><div id="record-picker" class="record-picker"></div></details></div><details id="recipe-details" open><summary>Editable JSON recipe (advanced)</summary><label class="sr-only" for="recipe">Investigation JSON</label><textarea name="recipe" id="recipe" rows="17" required maxlength="65536" spellcheck="false"><?=h($raw)?></textarea><button type="button" class="secondary" id="load-builder" hidden>Load JSON into visual builder</button></details><input type="hidden" name="expected" id="expected" value="<?=h($expected)?>"><div class="actions"><button type="submit" name="action" value="run">Run investigation</button><button type="submit" name="action" value="download" class="secondary">Run & download JSON</button><button type="button" id="agent-run" class="secondary" hidden>Run with AG-UI events</button><button type="button" id="cancel-run" class="secondary" hidden>Cancel display</button><button type="button" id="save-recipe" class="secondary" hidden>Save recipe</button><label id="import-label" hidden class="button secondary" for="import-file">Import recipe / result</label><input type="file" id="import-file" class="sr-only" accept=".json,application/json" hidden></div><p class="muted" id="workspace-status" role="status">Ready. Case order determines each model’s reference case.</p><p id="replay-status" class="muted"></p></section></form><section id="agent-log" class="panel section" hidden><h2>Agent event monitor</h2><progress id="run-progress" max="8" value="0"></progress><p id="agent-message" role="status"></p><ol id="event-list"></ol></section><div id="results"><?php if($r)render_result($r,$match);?></div><section class="panel section"><h2>Scientific interpretation rules</h2><p>The research question is recorded, not answered by an LLM. Model parameters must remain within their defined bounds. Plots use individual axis ranges; numerical deltas are only computed for the same model against its first case; independent controls do not form a joint model or likelihood. All source gates stay open unless independently established in the research.</p><p>Recipes and results stay in your browser or your downloaded files. Requests are computed on the server without application-level persistence; your host may retain request logs. No private project memory or original publication is included here.</p></section><script type="application/json" id="workspace-catalog"><?=j(catalog())?></script><?php endpage();}
function presets_page():void{start('Guided scientific investigations','Five editable multi-case investigations connecting numerical controls and original scientific evidence.',ROOT.'presets/');?><section class="intro"><span class="eyebrow gold">INVESTIGATION LIBRARY</span><h1>Start with a scientific question.</h1><p class="lead">Choose a research recipe, examine its reference case and change the parameters. Each investigation can be edited, extended and exported.</p></section><div class="record-grid"><?php foreach(presets() as $id=>$p):?><article class="panel"><span class="eyebrow"><?=count($p['plan']['cases'])?> ordered cases</span><h2><?=h($p['title'])?></h2><p><?=h($p['description'])?></p><p class="muted"><?=h($p['plan']['question'])?></p><a class="button" href="/research/?preset=<?=h($id)?>">Open recipe →</a></article><?php endforeach;?></div><?php endpage();}
function protocol_page():void{start('Research agent and replay protocol','Discover the native deterministic multi-case investigation API, replay hashes and AG-UI event subset.',ROOT.'protocol/');$p=presets()['escape']['plan'];?><section class="intro"><span class="eyebrow gold">MACHINE INTELLIGENCE INTERFACE</span><h1>Run scientific investigations programmatically.</h1><p class="lead">A bounded deterministic execution service, not a conversational language model. The plan explicitly chooses the calculations and evidence to retrieve.</p></section><section class="panel"><h2>Endpoints</h2><p><a href="/research/catalog.json">GET /research/catalog.json</a> — model definitions, parameter bounds, presets, evidence and validation gates.</p><p><a href="/research/api/">GET /research/api/</a> — live catalog and capabilities.</p><p><code>POST /research/api/</code> with Content-Type: application/json — submit a plan with optional expected_sha256 for a replay comparison.</p><pre><?=h(json_encode(['plan'=>$p],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre><h2>Native AG-UI event sequence</h2><p>Submit the same recipe under state.plan. Include threadId, runId and messages; the service does not interpret natural language, tool instructions, or external URLs.</p><pre><?=h(json_encode(['threadId'=>'example','runId'=>'run-1','messages'=>[],'state'=>['plan'=>$p],'tools'=>[],'context'=>[]],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre><p>Event order: RUN_STARTED; one STEP_STARTED and STEP_FINISHED pair per case; TEXT_MESSAGE_START, TEXT_MESSAGE_CONTENT, TEXT_MESSAGE_END; STATE_SNAPSHOT; RUN_FINISHED. An unexpected execution failure produces RUN_ERROR. Invalid input produces HTTP 400 before the stream starts. Transport is POST SSE; intermediaries may buffer events. See <a href="https://docs.ag-ui.com/concepts/events">AG-UI event specification ↗</a>. Only this subset is implemented; no full SDK certification, interrupt/resume, arbitrary tools, LLM or cross-origin access.</p><h2>Reproducibility contract</h2><p>The result includes the canonical normalized recipe (defaults expanded; evidence IDs sorted; case order retained), SHA-256 of its compact PHP JSON representation, full results, evidence, gates and SHA-256 hashes of all installed model and catalog files plus workspace code. The final result_sha256 hashes the result before that field is appended. PHP version and numerical formatting are included in the provenance; cross-runtime bit-for-bit reproducibility is not guaranteed.</p><p>Re-submit the recipe with expected_sha256 set to a previously exported result_sha256. The server returns a freshly calculated result and a replay match indicator. A digest match does not certify authenticity, rights or physical truth.</p><h2>Limits and privacy</h2><p>One to eight cases, 64 KiB request body, 26 evidence IDs, numeric bounds per model, no unknown recipe fields, no external calls, no application-level storage. Serve behind standard hosting request limits and rate limits; HTTPS required on production. Source files must be protected from direct HTTP access.</p></section><?php endpage();}
